# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">HADİS TARİHİNDE TEDVİN VE TASNİF SÜRECİNİN KARŞILAŞTIRILMASI</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">TEDVİN DÖNEMİ (HİCRİ I. ASIR SONU - II. ASIR)</text>\n  <text x="35" y="88" font-size="11.2" fill="#1e3a8a">• Anlamı: Dağınık hâldeki yazılı sahîfelerin ve</text>\n  <text x="45" y="104" font-size="11.2" fill="#1e3a8a">hafızalardaki hadislerin resmi emirle toplanmasıdır.</text>\n  <text x="35" y="128" font-size="11.2" fill="#1e3a8a">• Öncüleri: Halife Ömer bin Abdülaziz (emri veren)</text>\n  <text x="45" y="144" font-size="11.2" fill="#1e3a8a">ve İbn Şihâb ez-Zührî (ilk tedvini gerçekleştiren).</text>\n  <text x="35" y="168" font-size="11.2" fill="#1e3a8a">• Özelliği: Hadisler kaybolmaktan korunmuş, ancak</text>\n  <text x="45" y="184" font-size="11.2" fill="#1e3a8a">henüz konularına veya ravilerine göre ayrılmamıştır.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">TASNİF DÖNEMİ (HİCRİ II. ASIR ORTASI - III. ASIR)</text>\n  <text x="370" y="88" font-size="11.2" fill="#14532d">• Anlamı: Toplanan hadislerin belirli bir sisteme</text>\n  <text x="380" y="104" font-size="11.2" fill="#14532d">(konularına veya ravilerine) göre sınıflandırılmasıdır.</text>\n  <text x="370" y="128" font-size="11.2" fill="#14532d">• Yöntemleri: 1) Ale\'l-Ebvâb (Konularına göre),</text>\n  <text x="380" y="144" font-size="11.2" fill="#14532d">2) Ale\'r-Ricâl (Sahabi ravilerine göre).</text>\n  <text x="370" y="168" font-size="11.2" fill="#14532d">• Özelliği: Hicri III. asır \'Altın Çağ\' olmuş; Kütüb-i</text>\n  <text x="380" y="184" font-size="11.2" fill="#14532d">Sitte ve Kütüb-i Tis\'a bu dönemde telif edilmiştir.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Ortak Yön: Her iki süreç de Sünneti korumayı, uydurma (mevzû) rivayetleri önlemeyi ve gelecek nesillere aktarmayı amaçlar.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">TASNİF DÖNEMİ HADİS EDEBİYATI TÜRLERİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#92400e">KONULARINA GÖRE (ALE\'L-EBVÂB) ESERLER</text>\n  <text x="35" y="88" font-size="11.1" fill="#78350f">• Musannef / Muvatta: Merfû, mevkûf ve maktû</text>\n  <text x="45" y="104" font-size="10.8" fill="#78350f">haberleri fıkıh konularına göre dizer (İmam Mâlik).</text>\n  <text x="35" y="128" font-size="11.1" fill="#78350f">• Câmi\': İman, ahkâm, ahlak, tefsir, siyer ve fiten</text>\n  <text x="45" y="144" font-size="10.8" fill="#78350f">dâhil tüm ana konuları (8 ana bölüm) kapsar.</text>\n  <text x="35" y="168" font-size="11.1" fill="#78350f">• Sünen: İbadet, muamelat ve ukubat gibi ahkâm</text>\n  <text x="45" y="184" font-size="10.8" fill="#78350f">(fıkıh) konularındaki merfû hadisleri toplar.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#6b21a8">RAVİLERİNE GÖRE (ALE\'R-RİCÂL) ESERLER</text>\n  <text x="370" y="88" font-size="11.1" fill="#581c87">• Müsned: Hadisleri konularına göre değil, ilk</text>\n  <text x="380" y="104" font-size="10.8" fill="#581c87">ravi olan sahabilerin isimlerine göre sıralar.</text>\n  <text x="370" y="128" font-size="11.1" fill="#581c87">• En meşhuru: Ahmed bin Hanbel\'in \'el-Müsned\'i</text>\n  <text x="380" y="144" font-size="10.8" fill="#581c87">(yaklaşık 30.000 hadis içerir).</text>\n  <text x="370" y="168" font-size="11.1" fill="#581c87">• Mu\'cem: Hadisleri sahabilerin veya müellifin</text>\n  <text x="380" y="184" font-size="10.8" fill="#581c87">hocalarının alfabetik sırasına göre dizer (Taberânî).</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Aranan bir konudaki hadisi bulmak Câmi\' ve Sünen\'de kolay; ravisi bilinen hadisi bulmak ise Müsned\'de kolaydır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">KÜTÜB-İ SİTTE (6 TEMEL ESER) VE KÜTÜB-İ TİS\'A (9 ESER)</text>\n  <rect x="22" y="42" width="430" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="237" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#065f46">KÜTÜB-İ SİTTE (SAHÎHAYN + SÜNEN-İ ERBAA)</text>\n  <text x="35" y="88" font-size="10.8" fill="#064e3b">1. Buhârî (ö. 256/870) — el-Câmiu\'s-Sahîh (Câmi\' türü · Sahîhayn)</text>\n  <text x="35" y="108" font-size="10.8" fill="#064e3b">2. Müslim (ö. 261/875) — el-Câmiu\'s-Sahîh (Câmi\' türü · Sahîhayn)</text>\n  <text x="35" y="128" font-size="10.8" fill="#064e3b">3. Tirmizî (ö. 279/892) — es-Sünen / el-Câmi\' (Hem Câmi\' hem Sünen)</text>\n  <text x="35" y="148" font-size="10.8" fill="#064e3b">4. Ebû Dâvûd (ö. 275/888) — es-Sünen (Sünen-i Erbaa)</text>\n  <text x="35" y="168" font-size="10.8" fill="#064e3b">5. Nesâî (ö. 303/915) — es-Sünen (el-Müctebâ · Sünen-i Erbaa)</text>\n  <text x="35" y="188" font-size="10.8" fill="#064e3b">6. İbn Mâce (ö. 273/886) — es-Sünen (Sünen-i Erbaa)</text>\n  <rect x="464" y="42" width="214" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="571" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#9a3412">KÜTÜB-İ TİS\'A EKLEMELERİ</text>\n  <text x="475" y="92" font-size="10.8" fill="#7c2d12">Kütüb-i Sitte\'ye eklenen 3 eser:</text>\n  <text x="475" y="118" font-size="10.8" font-weight="bold" fill="#7c2d12">7. İmam Mâlik (ö. 179/795):</text>\n  <text x="485" y="134" font-size="10.5" fill="#7c2d12">el-Muvatta\'</text>\n  <text x="475" y="156" font-size="10.8" font-weight="bold" fill="#7c2d12">8. Ahmed b. Hanbel (ö. 241):</text>\n  <text x="485" y="172" font-size="10.5" fill="#7c2d12">el-Müsned</text>\n  <text x="475" y="194" font-size="10.8" font-weight="bold" fill="#7c2d12">9. Dârimî (ö. 255/869): es-Sünen</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Buhârî ve Müslim\'in eserlerine \'Sahîhayn\', ikisinin ortaklaşa rivayet ettiği hadislere \'Müttefekun Aleyh\' denir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
